<?php require __DIR__.'/../config/functions.php'; require_admin(); $db=get_db(); if(isset($_GET['toggle'])){$db->prepare('UPDATE members SET status=1-status WHERE id=?')->execute(array((int)$_GET['toggle']));} if($_SERVER['REQUEST_METHOD']==='POST'){$db->prepare('UPDATE members SET credits=credits+?,level=? WHERE id=?')->execute(array((int)$_POST['credits'],$_POST['level'],(int)$_POST['id']));} $list=$db->query('SELECT * FROM members ORDER BY id DESC')->fetchAll(); page_header('会员管理'); ?><div class="card wide"><h2>会员管理</h2><table><tr><th>ID</th><th>账号</th><th>等级</th><th>积分</th><th>状态</th><th>操作</th></tr><?php foreach($list as $r) echo '<tr><td>'.$r['id'].'</td><td>'.esc($r['email'].' '.$r['phone']).'</td><td>'.esc($r['level']).'</td><td>'.$r['credits'].'</td><td>'.($r['status']?'正常':'封禁').'</td><td><a href="?toggle='.$r['id'].'">封禁/解封</a><form method="post" style="display:inline"><input type="hidden" name="id" value="'.$r['id'].'"><input name="credits" value="0" style="width:70px"><input name="level" value="'.esc($r['level']).'" style="width:80px"><button>充值/调级</button></form></td></tr>'; ?></table></div><?php page_footer(); ?>
